/* Admin landing: next actions over module inventory. */
 function cockpit(){const v=globalThis.RodavoltCockpit.overview(ops,baseline),s=v.summary;return `<section class="cockpit-hero"><div><span class="eyebrow">SUA OPERAÇÃO, PASSO A PASSO</span><h1>Clareza para decidir.<br>Tranquilidade para rodar.</h1><p>Do primeiro carro à próxima compra. Saiba o que conferir e encontre cada ação no mesmo lugar.</p><div class="actions">${btn('Planejar a compra ↗','go-simulator','primary')}${btn('Testar a operação','cockpit-test')}</div></div><div class="cockpit-pilot"><span class="small-label">PRIMEIRO CARRO</span><strong>${esc(ops.vehicle.model)}</strong><span>${esc(ops.vehicle.plate)} · 100% elétrico</span><div class="pilot-track"><i></i><i></i><i></i><i></i></div><small>Simulação → preparação → entrega → rotina</small></div></section><div class="stats gap">${stat('Caixa livre de obrigações',cash(v.freeCash),'Caução e créditos separados',true,'cash-source')}${stat('Caução e créditos a devolver',cash(v.liabilities),'São obrigações dentro do caixa')}${stat('Aluguel a receber',cash(s.openRent),s.pendingProofs+' comprovante(s) para conferir')}${stat('Motoristas rodando',String(v.active.length),v.cars.length+' carro(s) cadastrado(s)')}</div><div class="cockpit-shortcuts">${[['＋','Receita','cockpit-income'],['−','Despesa','cockpit-expense'],['◷','Compromisso','go-agenda'],['§','Contrato','go-lawyer'],['▦','Repor produtos','go-shop'],['◉','Acompanhar motorista','go-live']].map(([icon,label,action])=>`<button data-action="${action}" type="button"><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</div><div class="columns-main gap"><div class="stack">${panel('O que precisa de você',task('＄','Aluguéis e comprovantes',cash(s.openRent)+' em aberto · confirme somente o que recebeu.','go-finance','Conferir')+(v.contractReturns.length?task('§','Contratos devolvidos',v.contractReturns.length+' arquivo(s) aguardando sua conferência.','go-lawyer','Conferir PDF'):'')+(v.inspections.length?task('▱','Vistorias enviadas',v.inspections.length+' vistoria(s) aguardando aprovação.','go-fleet','Conferir'):'')+(v.requests.length?task('↗','Mensagens dos motoristas',v.requests.length+' solicitação(ões) aguardando atendimento.','requests','Responder'):'')+task('◷','Compromissos da operação','Cobranças, agenda e cuidados com o carro.','go-agenda','Ver agenda'))}${panel('Lojinha · reposição antes de acabar',v.lowStock.length?v.lowStock.map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><small>${esc(p.driverName)} · central: ${p.central} un.</small></div><div>${tag(p.available+' disponível(is)',p.available===0?'red':'amber')}${btn('Preparar combo','cockpit-restock','',`data-driver="${esc(p.driverId)}"`)}</div></div>`).join(''):'<div class="notice">Nenhum produto com 2 unidades ou menos nos kits ativos.</div>','', 'Atualizado pelas vendas, reservas e conferências. O alerta não envia mercadoria sozinho.')}</div><div class="stack">${panel('Seu caminho para começar',`<ol class="launch-steps">${v.steps.map((step,i)=>`<li><span class="launch-number">${i+1}</span><div><strong>${step.title}</strong><p>${step.detail}</p>${btn('Abrir',''+step.action)}</div></li>`).join('')}</ol>`,'','Os dados atuais são de homologação. Use o roteiro para preencher e conferir cada etapa.')}</div></div>`;}
 function cockpitAction(action,e){if(action==='cockpit-income'||action==='cockpit-expense'){page='finance';finView='titles';finTitleFilter=action==='cockpit-income'?'receivable':'payable';render();persist();return true;}if(action==='cockpit-restock'){shopDriverId=e.dataset.driver;page='shop';render();persist();return true;}if(action==='cockpit-test'){open('Ensaio do primeiro carro',`<p>Faça o ensaio com dados fictícios. Cada etapa abaixo abre a tela que grava o registro; avançar neste roteiro não aprova nenhuma pendência.</p><ol class="launch-steps">${globalThis.RodavoltCockpit.overview(ops,baseline).steps.map((s,i)=>`<li><span class="launch-number">${i+1}</span><div><h3>${s.title}</h3><p>${s.detail}</p>${btn('Começar esta etapa',s.action)}</div></li>`).join('')}</ol><div class="notice">Depois da entrega: entre com o acesso do motorista em /operacao, envie check-in e vistoria, registre a venda e retorne à gestão para conferir estoque, dinheiro e documentos.</div>`);return true;}return false;}
